reference.setup:
{
    alpha <- 0.05
    complete_rows <- function(...) {
        m <- do.call(cbind, list(...))
        m[stats::complete.cases(m), , drop = FALSE]
    }
    gauss <- local({
        i <- 1:11
        b <- i/sqrt(4 * i^2 - 1)
        e <- eigen(diag(0, 12) + `[<-`(matrix(0, 12, 12), cbind(c(i, i + 1), c(i + 
            1, i)), c(b, b)), symmetric = TRUE)
        list(x = e$values, w = 2 * e$vectors[1, ]^2)
    })
    on_pieces <- function(br) {
        a <- head(br, -1)
        h <- diff(br)/2
        list(x = as.vector(outer(gauss$x, h) + rep(a + h, each = 12)), w = as.vector(outer(gauss$w, 
            h)))
    }
    x_nodes <- function(c, df) {
        top <- qchisq(1e-16, df, lower.tail = FALSE)
        k <- df * (seq(0.5, 3 * sqrt(df) + 10, by = 0.5)/c)^2
        on_pieces(sort(unique(c(0, qchisq(c(1e-13, 1e-10, 1e-07, 1e-04, 0.01, 0.2, 
            0.5, 0.8, 0.99, 1 - 1e-07), df), k[k < top], top))))
    }
    dunnett <- function(c, lam, df) {
        sig <- sqrt(1 - lam^2)
        xn <- x_nodes(c, df)
        zt <- on_pieces(seq(-1, 1, length.out = 61))
        given_x <- vapply(xn$x, function(x) {
            s <- sqrt(x/df)
            reach <- (c * s + 9)/min(lam) + 2
            z <- reach * zt$x
            q <- pmin(pnorm(outer(z, lam, function(z, l) (-c * s - l * z))/rep(sig, 
                each = length(z))) + pnorm(outer(z, lam, function(z, l) (c * s - 
                l * z))/rep(sig, each = length(z)), lower.tail = FALSE), 1)
            reach * sum(zt$w * dnorm(z) * (1 - exp(rowSums(log1p(-q))))) + 2 * pnorm(-reach)
        }, 0)
        min(1, sum(xn$w * dchisq(xn$x, df) * given_x))
    }
    critical <- function(p) uniroot(function(c) p(c) - alpha, c(0.5, 50), tol = 1e-13)$root
    repeated <- function(m, comps = "all", control = 1, test = "tukey", sphericity = TRUE) {
        n <- nrow(m)
        k <- ncol(m)
        d <- data.frame(value = as.vector(t(m)), treat = factor(rep(seq_len(k), n)), 
            subj = factor(rep(seq_len(n), each = k)))
        fit <- aov(value ~ subj + treat, data = d)
        tab <- anova(fit)
        strat <- summary(aov(value ~ treat + Error(subj/treat), data = d))
        f_strat <- strat[["Error: subj:treat"]][[1]][1, "F value"]
        stopifnot(isTRUE(all.equal(unname(tab["treat", "F value"]), unname(f_strat), 
            tolerance = 1e-09)))
        means <- unname(tapply(d$value, d$treat, mean))
        mse <- tab["Residuals", "Mean Sq"]
        df_res <- tab["Residuals", "Df"]
        sph <- stats:::sphericity(stats::SSD(lm(m ~ 1)), X = ~1)
        clamp <- function(e) max(1/(k - 1), min(1, e))
        gg <- clamp(sph$GG.eps)
        hf <- clamp(sph$HF.eps)
        f <- unname(tab["treat", "F value"])
        out <- list(k = k, n = n, ss_treatment = unname(tab["treat", "Sum Sq"]), 
            ss_subjects = unname(tab["subj", "Sum Sq"]), ss_residual = unname(tab["Residuals", 
                "Sum Sq"]), ss_total = sum(tab[, "Sum Sq"]), df_treatment = unname(tab["treat", 
                "Df"]), df_subjects = unname(tab["subj", "Df"]), df_residual = unname(df_res), 
            df_total = n * k - 1, ms_treatment = unname(tab["treat", "Mean Sq"]), 
            ms_subjects = unname(tab["subj", "Mean Sq"]), ms_residual = unname(mse), 
            f = f, p = unname(tab["treat", "Pr(>F)"]), gg_epsilon = gg, hf_epsilon = hf, 
            gg_p = pf(f, (k - 1) * gg, df_res * gg, lower.tail = FALSE), hf_p = pf(f, 
                (k - 1) * hf, df_res * hf, lower.tail = FALSE), r_squared_treatment = unname(tab["treat", 
                "Sum Sq"]/(tab["treat", "Sum Sq"] + tab["Residuals", "Sum Sq"])), 
            r_squared_subjects = unname(tab["subj", "Sum Sq"]/sum(tab[, "Sum Sq"])), 
            groups = lapply(seq_len(k), function(j) list(mean = means[j])))
        out$comparisons <- if (comps == "none") 
            list()
        else {
            pairs <- unname(if (comps == "all") {
                do.call(rbind, lapply(seq_len(k - 1), function(i) cbind(i, (i + 1):k)))
            }
            else {
                cbind(control, seq_len(k)[-control])
            })
            K <- nrow(pairs)
            if (sphericity) {
                hsd <- if (test == "tukey") 
                  TukeyHSD(fit, "treat", conf.level = 1 - alpha)$treat
                else NULL
                if (test == "dunnett") {
                  others <- pairs[, 2]
                  lam <- rep(sqrt(n/(n + n)), length(others))
                  dunnett_crit <- critical(function(c) dunnett(c, lam, df_res))
                }
                lapply(seq_len(K), function(x) {
                  i <- pairs[x, 1]
                  j <- pairs[x, 2]
                  dd <- means[i] - means[j]
                  se <- sqrt(mse * (2/n))
                  t <- abs(dd)/se
                  r <- switch(test, tukey = {
                    h <- hsd[paste0(j, "-", i), ]
                    list(stat = sqrt(2) * t, lower = -h[["upr"]], upper = -h[["lwr"]], 
                      p = h[["p adj"]])
                  }, bonferroni = {
                    half <- qt(1 - alpha/(2 * K), df_res) * se
                    list(stat = t, lower = dd - half, upper = dd + half, p = min(1, 
                      K * 2 * pt(t, df_res, lower.tail = FALSE)))
                  }, sidak = {
                    half <- qt(1 - (1 - (1 - alpha)^(1/K))/2, df_res) * se
                    p1 <- 2 * pt(t, df_res, lower.tail = FALSE)
                    list(stat = t, lower = dd - half, upper = dd + half, p = -expm1(K * 
                      log1p(-p1)))
                  }, dunnett = {
                    half <- dunnett_crit * se
                    list(stat = t, lower = dd - half, upper = dd + half, p = dunnett(t, 
                      lam, df_res))
                  })
                  list(i = i, j = j, diff = dd, se = se, df = df_res, statistic = r$stat, 
                    ci_lower = r$lower, ci_upper = r$upper, p = r$p)
                })
            }
            else {
                if (test == "dunnett") {
                  others <- pairs[, 2]
                  lam <- rep(sqrt(n/(n + n)), length(others))
                  dunnett_crit <- critical(function(c) dunnett(c, lam, n - 1))
                }
                lapply(seq_len(K), function(x) {
                  i <- pairs[x, 1]
                  j <- pairs[x, 2]
                  tt <- t.test(m[, i], m[, j], paired = TRUE)
                  dd <- unname(tt$estimate)
                  nu <- unname(tt$parameter)
                  t <- abs(unname(tt$statistic))
                  se <- abs(dd)/t
                  r <- switch(test, tukey = {
                    half <- qtukey(1 - alpha, k, nu)/sqrt(2) * se
                    list(stat = sqrt(2) * t, lower = dd - half, upper = dd + half, 
                      p = ptukey(sqrt(2) * t, k, nu, lower.tail = FALSE))
                  }, bonferroni = {
                    half <- qt(1 - alpha/(2 * K), nu) * se
                    list(stat = t, lower = dd - half, upper = dd + half, p = min(1, 
                      K * 2 * pt(t, nu, lower.tail = FALSE)))
                  }, sidak = {
                    half <- qt(1 - (1 - (1 - alpha)^(1/K))/2, nu) * se
                    p1 <- 2 * pt(t, nu, lower.tail = FALSE)
                    list(stat = t, lower = dd - half, upper = dd + half, p = -expm1(K * 
                      log1p(-p1)))
                  }, dunnett = {
                    half <- dunnett_crit * se
                    list(stat = t, lower = dd - half, upper = dd + half, p = dunnett(t, 
                      lam, nu))
                  })
                  list(i = i, j = j, diff = dd, se = se, df = nu, statistic = r$stat, 
                    ci_lower = r$lower, ci_upper = r$upper, p = r$p)
                })
            }
        }
        out
    }
}
